1	import java.math.BigDecimal;
2	import java.math.RoundingMode;
3	import java.util.List;
4	
5	public class ClaimOffice {
6	
7	    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
8	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = rate(10);
9	    private static final BigDecimal CURSE_SURCHARGE_RATE = rate(50);
10	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = rate(30);
11	
12	    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
13	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
14	
15	    private final Customer customer;
16	
17	    public ClaimOffice(Customer customer) {
18	        this.customer = customer;
19	    }
20	
21	    public int quote(List<Item> items) {
22	        BigDecimal policyBasePremium = MhpcoPriceList.policyBasePremiumOf(items);
23	        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
24	                .add(itemScopeContribution(items));
25	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
26	    }
27	
28	    /**
29	     * What the item scope contributes: the MHPCO charges a risk surcharge for each
30	     * risky item as a share of that item's own base premium, never of the policy total.
31	     */
32	    private static BigDecimal itemScopeContribution(List<Item> items) {
33	        return items.stream()
34	                .map(ClaimOffice::riskSurchargeFor)
35	                .reduce(BigDecimal.ZERO, BigDecimal::add);
36	    }
37	
38	    private static BigDecimal riskSurchargeFor(Item item) {
39	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
40	        BigDecimal surcharge = BigDecimal.ZERO;
41	        if (item.cursed()) {
42	            surcharge = surcharge.add(shareOf(itemBasePremium, CURSE_SURCHARGE_RATE));
43	        }
44	        if (isHighlyEnchanted(item)) {
45	            surcharge = surcharge.add(
46	                    shareOf(itemBasePremium, HIGH_ENCHANTMENT_SURCHARGE_RATE));
47	        }
48	        return surcharge;
49	    }
50	
51	    private static boolean isHighlyEnchanted(Item item) {
52	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
53	    }
54	
55	    /**
56	     * What the policy scope contributes: the policy base premium itself, adjusted by
57	     * the modifiers the office applies to the policy as a whole.
58	     */
59	    private BigDecimal policyScopeContribution(BigDecimal policyBasePremium) {
60	        return policyBasePremium
61	                .add(shareOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_RATE));
62	    }
63	
64	    /** A modifier is a percentage share of the amount it applies to. */
65	    private static BigDecimal shareOf(BigDecimal amount, BigDecimal modifierRate) {
66	        return amount.multiply(modifierRate);
67	    }
68	
69	    /** A modifier rate stated the way the price list states it: in whole percent. */
70	    private static BigDecimal rate(int percent) {
71	        return BigDecimal.valueOf(percent, 2);
72	    }
73	
74	    /**
75	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
76	     * amounts stay exact fractions, so only this final step loses the remainder.
77	     */
78	    private static int roundInOfficeFavour(BigDecimal premium) {
79	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
80	    }
81	}
