1	import java.math.BigDecimal;
2	import java.util.List;
3	import java.util.Map;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	/**
8	 * The MHPCO price list: what the office charges as a base premium for the items it
9	 * covers, before any modifier that depends on the customer or the contract.
10	 */
11	public final class MhpcoPriceList {
12	
13	    /** Base premium in G per main item type. */
14	    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_BY_TYPE = Map.of(
15	            "sword", 100,
16	            "amulet", 60,
17	            "staff", 80,
18	            "potion", 40);
19	
20	    /**
21	     * Components are a family of small item types the MHPCO prices alike: every
22	     * component costs the same base premium, whatever its type.
23	     */
24	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
25	
26	    private static final int COMPONENT_BASE_PREMIUM = 25;
27	
28	    /** A building block of exactly 3 alike components is offered at a special price. */
29	    private static final int COMPONENT_BLOCK_SIZE = 3;
30	    private static final int COMPONENT_BLOCK_BASE_PREMIUM = 60;
31	
32	    /**
33	     * Placeholder for types not yet in the price list. The specification treats an
34	     * unknown type as an error; until that behavior is implemented, unlisted types
35	     * fall back to the sword price rather than to an invented "unlisted item" price.
36	     */
37	    private static final int UNLISTED_TYPE_PLACEHOLDER_PREMIUM =
38	            MAIN_ITEM_BASE_PREMIUM_BY_TYPE.get("sword");
39	
40	    private MhpcoPriceList() {
41	    }
42	
43	    /**
44	     * The policy base premium: every main item at its price-list premium, plus each
45	     * group of alike components priced together so building blocks can be recognised.
46	     */
47	    public static BigDecimal policyBasePremiumOf(List<Item> items) {
48	        BigDecimal mainItems = items.stream()
49	                .filter(item -> !isComponent(item))
50	                .map(MhpcoPriceList::mainItemBasePremiumOf)
51	                .reduce(BigDecimal.ZERO, BigDecimal::add);
52	        BigDecimal components = alikeComponentCounts(items).values().stream()
53	                .map(MhpcoPriceList::alikeComponentsBasePremiumOf)
54	                .reduce(BigDecimal.ZERO, BigDecimal::add);
55	        return mainItems.add(components);
56	    }
57	
58	    /**
59	     * What a single item costs on its own, ignoring any building block it belongs to.
60	     * Item risk surcharges are shares of this amount.
61	     */
62	    public static BigDecimal basePremiumOf(Item item) {
63	        if (isComponent(item)) {
64	            return BigDecimal.valueOf(COMPONENT_BASE_PREMIUM);
65	        }
66	        return mainItemBasePremiumOf(item);
67	    }
68	
69	    /** How many components of each type the policy covers, grouped by their type. */
70	    private static Map<String, Long> alikeComponentCounts(List<Item> items) {
71	        return items.stream()
72	                .filter(MhpcoPriceList::isComponent)
73	                .collect(Collectors.groupingBy(Item::type, Collectors.counting()));
74	    }
75	
76	    /**
77	     * What the office charges for the alike components of one type: a building block
78	     * is offered at its special price, anything else is priced component by component.
79	     */
80	    private static BigDecimal alikeComponentsBasePremiumOf(long alikeCount) {
81	        if (formsBuildingBlock(alikeCount)) {
82	            return BigDecimal.valueOf(COMPONENT_BLOCK_BASE_PREMIUM);
83	        }
84	        return BigDecimal.valueOf(alikeCount * COMPONENT_BASE_PREMIUM);
85	    }
86	
87	    /** The block price is offered for exactly 3 alike components -- no more, no less. */
88	    private static boolean formsBuildingBlock(long alikeCount) {
89	        return alikeCount == COMPONENT_BLOCK_SIZE;
90	    }
91	
92	    private static BigDecimal mainItemBasePremiumOf(Item item) {
93	        return BigDecimal.valueOf(MAIN_ITEM_BASE_PREMIUM_BY_TYPE.getOrDefault(
94	                item.type(), UNLISTED_TYPE_PLACEHOLDER_PREMIUM));
95	    }
96	
97	    private static boolean isComponent(Item item) {
98	        return COMPONENT_TYPES.contains(item.type());
99	    }
100	}
